        const material = new THREE.MeshStandardMaterial({ color: body.appearance?.color ?? 0x4faaa5, roughness: body.appearance?.roughness ?? .48, metalness: body.appearance?.metalness ?? .18, side: THREE.DoubleSide }); materials.push(material);
        const mesh = new THREE.Mesh(geometry, material); mesh.position.set(mmToWorld(placement.translationMm.x), mmToWorld(placement.translationMm.y), mmToWorld(placement.translationMm.z)); mesh.quaternion.set(placement.rotation.x, placement.rotation.y, placement.rotation.z, placement.rotation.w); mesh.userData = { componentId, definitionId: component.definitionId, bodyId, tessellation, definitionRuntime }; scene.add(mesh); meshes.push(mesh); const owned=componentMeshes.get(componentId)??[]; owned.push(mesh); componentMeshes.set(componentId,owned);
