      for(const componentId of targetDocument.componentOrder){const component=targetDocument.components[componentId];const definition=definitionsRef.current.definitions.get(component.definitionId);if(!definition)continue;for(const connectorId of definition.mateConnectorOrder){try{const ref={instanceId:componentId,connectorId};const local=await provider.resolveConnector(ref);explicitConnectorCache.push({ref,local});const placement=targetRuntime.solvedPlacements.get(componentId)??component.nominalPlacement;const frame=transformMateConnectorFrame(local,placement);const origin=new THREE.Vector3(mmToWorld(frame.originMm.x),mmToWorld(frame.originMm.y),mmToWorld(frame.originMm.z));const length=.024;for(const [axis,color] of [[frame.primaryAxis,0xec4899],[frame.secondaryAxis,0x22d3ee],[frame.tertiaryAxis,0xa3e635]] as const)connectorGroup.add(new THREE.ArrowHelper(new THREE.Vector3(axis.x,axis.y,axis.z),origin,length,color,length*.2,length*.1));}catch{/* connector diagnostics surface through commands */}}}
