    const raycaster = new THREE.Raycaster(); let suppressClick=false; let dragState: undefined | { componentId:string; plane:THREE.Plane; startWorld:THREE.Vector3; baseDocument:AssemblyDocument; basePlacement:RigidTransform; latestDocument:AssemblyDocument; sequence:number; moved:boolean; lastSolveAt:number };
    const pointerNdc=(event:PointerEvent|MouseEvent)=>{const rect=renderer.domElement.getBoundingClientRect();return new THREE.Vector2(((event.clientX-rect.left)/rect.width)*2-1,-((event.clientY-rect.top)/rect.height)*2+1);};
