     const onPointerUp=(event:PointerEvent)=>{ if(!dragState)return; const final=dragState.latestDocument,moved=dragState.moved; dragState=undefined; try{renderer.domElement.releasePointerCapture(event.pointerId);}catch{/* pointer capture may already be released */} controls.enabled=interactionModeRef.current==="orbit"; if(moved) void solveAndPublish(final); };
