      try { const topologyRef = await capturePersistentTopologyRef(tipFeatureId, localSelection.topology, data.definitionRuntime.runtime, kernel); const face = await kernel.getFaceInfo(localSelection.topology); const slot = { label: `${data.componentId}/${data.bodyId} · ${face.surfaceType ?? "面"}`, reference: { instanceId: data.componentId, bodyId: data.bodyId, topologyRef } }; let nextSlots:FaceSlot[]=[]; setFaceSlots((current) => { nextSlots=current.length >= 2 ? [slot] : [...current, slot]; return nextSlots; }); await setMateConnectors(nextSlots); setStatus(`已选择 ${slot.label} · ${face.surfaceType === "plane" ? "可添加重合、距离或角度配合" : face.surfaceType === "cylinder" ? "可添加同心配合" : "请检查曲面是否支持当前配合"}`); } catch (error) { setStatus(error instanceof Error ? error.message : String(error)); }
